  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:

   Mathematically, the original kernel computes, with SIDE='L', UPLO='L',

       C := alpha * Symm(A) * B + beta * C,

   where Symm(A) is the full symmetric matrix whose lower triangle is
   stored in A (the upper triangle is never used).

   The original code uses a triangular i–j–k loop nest with a scalar
   temporary 'temp2'. It has poor cache behavior for B and C because
   the inner loop iterates over k (the non-contiguous dimension).

   This optimized kernel performs the same computation but with:

     1) A separate, simple pass scaling C by beta (good locality,
        trivially vectorizable);

     2) A reordered symmetric rank-1 update scheme that:
        - uses only the initialized lower triangle of A,
        - makes the innermost loops run over j (unit-stride access for
          B and C, good for SIMD and caches),
        - introduces small per-tile temporary buffers over j to
          increase data reuse and reduce multiplications by alpha.

   Algebraic equivalence (real arithmetic):

     For each i and j, the original kernel yields

       C[i,j] = beta * C0[i,j]
                + alpha * A[i,i] * B[i,j]
                + alpha * sum_{k=0..i-1} A[i,k] * B[k,j]
                + alpha * sum_{k=i+1..M-1} A[k,i] * B[k,j],

     which is exactly (alpha * Symm(A) * B + beta * C0)[i,j].

   The algorithm below computes the same expression but in a form that
   is much friendlier to modern CPUs.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  int J;

  /* Small per-tile temporaries over the column dimension (j).
     temp1[jt]  holds alpha * B[i][J+jt]  for a fixed (i, J)-tile.
     temp2[jt]  accumulates sum_{k<i} A[i,k] * B[k, J+jt] for that tile. */
  DATA_TYPE temp1[SYMM_J_BLOCK];
  DATA_TYPE temp2[SYMM_J_BLOCK];

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM (only lower triangle is initialized and used)
// B is MxN
// C is MxN
//note that due to Fortran array layout, the original code more closely
//resembles the upper triangular case in BLAS
#pragma scop

  /* 1. Scale C by beta.
     This is algebraically equivalent to the in-loop scaling in the
     original kernel but separates a simple, memory-bound operation
     from the more complex symmetric update. */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Ci = C[i];
    for (j = 0; j < _PB_N; j++) {
      Ci[j] *= beta;
    }
  }

  /* 2. Symmetric rank-1 style updates using the stored lower triangle of A.

     For each row index i:

       - temp1[j]  = alpha * B[i,j]      (per column j)
       - temp2[j]  = 0

       - For all k < i, we use A[i,k] to perform:
           C[k, j] += A[i,k] * temp1[j]          (contribution from row i to row k)
           temp2[j] += A[i,k] * B[k, j]          (to be used for row i)

       - Finally, using the diagonal A[i,i] and accumulated temp2:
           C[i, j] += A[i,i] * temp1[j] + alpha * temp2[j]

     Together with the initial C *= beta pass, this is exactly the
     same computation as the original kernel, but with j as the
     innermost loop, enabling good cache behavior and SIMD. */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *Bi = B[i];

    /* Process columns in blocks of SYMM_J_BLOCK to improve locality
       for B, C, and the temporaries. */
    for (J = 0; J < _PB_N; J += SYMM_J_BLOCK) {
      int j_end = J + SYMM_J_BLOCK;
      if (j_end > _PB_N)
        j_end = _PB_N;
      int jb_len = j_end - J;

      /* Precompute alpha * B[i, j] and initialize temp2 for this tile. */
      for (j = 0; j < jb_len; j++) {
        int col = J + j;
        DATA_TYPE Bij = Bi[col];
        temp1[j] = alpha * Bij;
        temp2[j] = 0;
      }

      /* Use the strictly lower part of row i of A: k in [0, i). */
      for (k = 0; k < i; k++) {
        DATA_TYPE a_ik = A[i][k]; /* Only valid for k <= i (lower triangle). */
        DATA_TYPE *Bk = B[k];
        DATA_TYPE *Ck = C[k];

        /* Rank-1 style update over the current column tile. */
        for (j = 0; j < jb_len; j++) {
          int col = J + j;
          DATA_TYPE Bkj = Bk[col];

          /* Contribution to row k from (i,k). */
          Ck[col] += a_ik * temp1[j];

          /* Partial sum for row i from (i,k). */
          temp2[j] += a_ik * Bkj;
        }
      }

      /* Diagonal and accumulated lower-triangular contribution to row i. */
      {
        DATA_TYPE a_ii = A[i][i];
        DATA_TYPE *Ci = C[i];

        for (j = 0; j < jb_len; j++) {
          int col = J + j;
          Ci[col] += a_ii * temp1[j] + alpha * temp2[j];
        }
      }
    } /* end J loop */
  }   /* end i loop */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
