  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Create restricted 2D views of the arrays.
     Using C99 VLAs here lets the compiler know the true row lengths,
     and __restrict tells it that A_, B_, and C_ do not alias each
     other, which aids vectorization and other optimizations. */
  DATA_TYPE (* __restrict A_)[m] = A; /* A: m x m, lower triangle stored */
  DATA_TYPE (* __restrict B_)[n] = B; /* B: m x n */
  DATA_TYPE (* __restrict C_)[n] = C; /* C: m x n */

  /* Small compile-time tiling factors tuned for cache locality.
     - TSM: tile size in the i (row) dimension
     - TSK: tile size in the k (shared) dimension
     - TSN: tile size in the j (column) dimension
     They do not need to divide m or n exactly; edge tiles are handled
     by truncating the upper bounds. */
  enum {
    TSM = 32,
    TSK = 32,
    TSN = 64
  };

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM (symmetric, lower triangle stored)
// B is MxN
// C is MxN
// We interpret A as the lower-triangular storage of a full symmetric
// matrix S with S(i,k) = (i >= k) ? A[i][k] : A[k][i].  Only the
// initialized lower triangle is ever read.

#pragma scop
  /* 1. Scale C by beta: C := beta * C.
     In the original kernel this multiplication by beta happens inside
     the main loop when i hits the row index.  Performing it here in a
     separate pass is algebraically equivalent:

         C_final = beta * C0 + alpha * S * B

     It also yields a very simple, fully vectorizable loop. */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++)
      C_[i][j] *= beta;

  /* 2. Symmetric matrix-matrix product:
         C := C + alpha * S * B

     where S is the full symmetric matrix defined by the lower triangle
     of A:

         S(i,k) = (i >= k) ? A[i][k] : A[k][i].

     Combining this with the scaling above reproduces the BLAS SYMM
     semantics (SIDE='L', UPLO='L') implemented by the original code.

     The loop nest is blocked in i, k, and j to improve cache locality:
     - j is innermost for unit-stride access to B and C (row-major),
       which enables efficient SIMD vectorization.
     - For each (i, k) pair, we form t = alpha * S(i,k) once and reuse
       it across the entire inner j-loop (scalar hoisting). */
  for (int ii = 0; ii < _PB_M; ii += TSM) {
    int i_max = ii + TSM;
    if (i_max > _PB_M)
      i_max = _PB_M;

    for (int kk = 0; kk < _PB_M; kk += TSK) {
      int k_max = kk + TSK;
      if (k_max > _PB_M)
        k_max = _PB_M;

      for (int jj = 0; jj < _PB_N; jj += TSN) {
        int j_max = jj + TSN;
        if (j_max > _PB_N)
          j_max = _PB_N;

        /* Contribution of the (ii..i_max-1) x (kk..k_max-1) block
           of S to the (ii..i_max-1) x (jj..j_max-1) block of C. */
        for (i = ii; i < i_max; i++) {
          for (k = kk; k < k_max; k++) {
            /* Access the symmetric matrix element from the stored
               lower triangle.  This mapping guarantees that we never
               read A[i][k] with k > i (the region initialized to -999). */
            DATA_TYPE s = (i >= k) ? A_[i][k] : A_[k][i];
            DATA_TYPE t = alpha * s;  /* invariant across j for this (i,k) */

            for (j = jj; j < j_max; j++) {
              C_[i][j] += t * B_[k][j];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

