/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k, jj;

  /* Tile size along the column dimension (j). Chosen to balance cache
     locality and stack usage of the temporary buffers. */
  enum { JB = 64 };

  /* Temporary buffers over a block of columns j in [jj, jj+JB).
     - temp1[jb] holds alpha * B[i][jj + jb] for the current row i.
     - temp2[jb] accumulates sum_{k < i} A[i,k] * B[k][jj + jb]
       for the current row i. */
  DATA_TYPE temp1[JB];
  DATA_TYPE temp2[JB];

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM
// B is MxN
// C is MxN
//note that due to Fortran array layout, the code below more closely resembles upper triangular case in BLAS
#pragma scop
  /* 1) Scale C by beta.
     This is separated from the symmetric product so that the hot kernel
     no longer pays the beta multiplication cost. The loop is simple,
     cache-friendly, and easy for the compiler to vectorize. */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++)
      C[i][j] *= beta;

  /* If alpha is zero, the operation reduces to C := beta * C, which
     has already been performed above. */
  if (alpha != (DATA_TYPE)0) {

    /* 2) Symmetric matrix-matrix product.
          This implements the standard BLAS SYMM(L, L) algorithm using
          only the stored lower triangle of A.

          For each row i of A:
            - temp1[:] = alpha * B[i, :]   (pre-scaled current row of B)
            - temp2[:] = 0
            - For k < i:
                * update row k of C with alpha * A[i,k] * B[i, :]
                * accumulate A[i,k] * B[k, :] into temp2
            - Finally update row i of C with:
                A[i,i] * temp1[:] + alpha * temp2[:]

          Algebraically this computes:
            C := beta * C + alpha * Symm(A) * B
          where Symm(A) is the full symmetric matrix induced by the
          lower triangle of A. */
    for (i = 0; i < _PB_M; i++) {
      /* Process columns in blocks of size JB to improve cache locality
         for B and C, and to keep the temporary buffers small and
         stack-resident. */
      for (jj = 0; jj < _PB_N; jj += JB) {
        int j_end = jj + JB;
        if (j_end > _PB_N)
          j_end = _PB_N;
        int jb_size = j_end - jj;

        /* Precompute temp1 = alpha * B[i, j] and zero temp2
           for the current column block. */
        for (j = 0; j < jb_size; j++) {
          DATA_TYPE Bij = B[i][jj + j];
          temp1[j] = alpha * Bij;
          temp2[j] = (DATA_TYPE)0;
        }

        /* Strictly lower triangular part: k = 0 .. i-1.
           Each A[i,k] contributes:
             - to row k of C: alpha * A[i,k] * B[i, j]    (via temp1),
             - to row i of C: alpha * A[i,k] * B[k, j]    (via temp2). */
        for (k = 0; k < i; k++) {
          DATA_TYPE a_ik = A[i][k];
          for (j = 0; j < jb_size; j++) {
            int col = jj + j;
            C[k][col] += a_ik * temp1[j];
            temp2[j]  += a_ik * B[k][col];
          }
        }

        /* Diagonal term A[i,i] and accumulated strictly lower part. */
        DATA_TYPE a_ii = A[i][i];
        for (j = 0; j < jb_size; j++) {
          int col = jj + j;
          C[i][col] += a_ii * temp1[j] + alpha * temp2[j];
        }
      }
    }
  }
#pragma endscop

}


