/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Effective loop bounds, as provided by PolyBench.
     These may differ from the raw sizes when running reduced problems. */
  const int m_eff = _PB_M;
  const int n_eff = _PB_N;

  /* Per-row temporaries.
   *
   * temp1[j] holds alpha * B[i][j] for the current row i.
   * temp2[j] accumulates sum_{k<i} A[i][k] * B[k][j] for the same row i.
   *
   * They are VLAs allocated on the stack; their size is O(N) and typically
   * much smaller than the full MxN matrices.
   */
  DATA_TYPE temp1[n_eff];
  DATA_TYPE temp2[n_eff];

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM (symmetric, lower triangle stored)
// B is MxN
// C is MxN
//note that due to Fortran array layout, the original code more closely resembles
//the upper triangular case in BLAS. The transformed kernel below computes the
//same mathematical result but with improved data locality and vectorization.
#pragma scop

  /* 1. Hoist the beta scaling of C into its own pass.
   *
   * Original kernel scales C[i][j] by beta exactly once, when processing row i.
   * Doing it here in a separate, fully regular loop is algebraically
   * equivalent:
   *
   *   C := beta * C + alpha * Symm(A) * B
   *
   * and makes the hot symmetric multiply free of beta, enabling a simpler
   * innermost loop.
   */
  for (i = 0; i < m_eff; ++i)
    for (j = 0; j < n_eff; ++j)
      C[i][j] *= beta;

  /* 2. Symmetric matrix-matrix product using only the lower triangle of A.
   *
   * For each row i, we conceptually compute:
   *
   *   C[i, j] += alpha * A[i, i] * B[i, j]
   *              + alpha * sum_{k<i} A[i, k] * B[k, j]
   *              + alpha * sum_{k>i} A[k, i] * B[k, j]
   *
   * but without ever reading the unused upper triangle A[i][k] (k>i).
   *
   * The loop below is an efficient formulation equivalent to the PolyBench
   * kernel:
   *   - For each fixed i, we:
   *       * precompute temp1[j] = alpha * B[i, j],
   *       * accumulate temp2[j] = sum_{k<i} A[i, k] * B[k, j],
   *         while simultaneously updating all C[k, j] for k<i,
   *       * finally update row i with the diagonal and accumulated terms.
   *
   * This matches BLAS SYMM (SIDE = 'L', UPLO = 'L') semantics and preserves
   * the original computation, while making the innermost loops iterate over
   * j (the contiguous dimension), which greatly improves cache behavior and
   * SIMD vectorization opportunities.
   */
  for (i = 0; i < m_eff; ++i)
  {
    /* Precompute alpha * B[i, j] and initialize the accumulator for row i. */
    for (j = 0; j < n_eff; ++j)
    {
      temp1[j] = alpha * B[i][j];
      temp2[j] = (DATA_TYPE)0;
    }

    /* Contributions from strictly lower part A[i, k] with k < i.
     *
     * For each k < i:
     *   - C[k, j] receives   alpha * A[i, k] * B[i, j]   via temp1,
     *   - temp2[j] accumulates       A[i, k] * B[k, j],
     *     which will later be multiplied by alpha when updating C[i, j].
     *
     * Only A[i, k] with k <= i-1 are accessed, so we never touch the
     * sentinel-filled upper triangle (k > i).
     */
    for (k = 0; k < i; ++k)
    {
      DATA_TYPE a_ik = A[i][k];

      for (j = 0; j < n_eff; ++j)
      {
        DATA_TYPE t1 = a_ik * temp1[j];  /* alpha * A[i,k] * B[i,j] */
        DATA_TYPE t2 = a_ik * B[k][j];   /*        A[i,k] * B[k,j] */

        C[k][j] += t1;
        temp2[j] += t2;
      }
    }

    /* Diagonal and accumulated lower-part contributions for row i.
     *
     * After the loop over k:
     *   temp2[j] = sum_{k<i} A[i, k] * B[k, j]
     *
     * so this loop performs:
     *   C[i, j] += alpha * A[i, i] * B[i, j]
     *             + alpha * sum_{k<i} A[i, k] * B[k, j]
     *
     * Contributions from k > i (the "upper" part of the symmetric matrix)
     * are added to C[i, j] when those rows k are processed in later
     * iterations of the outer loop, exactly as in the original kernel.
     */
    {
      DATA_TYPE a_ii = A[i][i];
      for (j = 0; j < n_eff; ++j)
      {
        C[i][j] += a_ii * temp1[j] + alpha * temp2[j];
      }
    }
  }

#pragma endscop

